package app.multimin.ui;
import javax.swing.*;
import java.awt.*;
final class AppNotice {
 private AppNotice(){}
 static int show(Component parent,Palette palette,String title,String message,String... choices){Window owner=parent==null?null:parent instanceof Window w?w:SwingUtilities.getWindowAncestor(parent);JDialog dialog=new JDialog(owner,title,Dialog.ModalityType.APPLICATION_MODAL);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.setResizable(true);JPanel body=new JPanel(new BorderLayout(12,18));body.setBackground(palette.background);body.setBorder(BorderFactory.createEmptyBorder(18,20,16,20));JLabel heading=new JLabel(title);heading.setFont(new Font(Font.DIALOG,Font.BOLD,16));heading.setForeground(palette.text);body.add(heading,BorderLayout.NORTH);JTextArea text=new JTextArea(message);text.setFont(new Font(Font.DIALOG,Font.PLAIN,13));text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setOpaque(false);text.setForeground(palette.text);text.setBorder(null);text.setCaretPosition(0);JScrollPane scroll=new JScrollPane(text);scroll.setBorder(null);scroll.setOpaque(false);scroll.getViewport().setOpaque(false);ModernUi.scroll(scroll.getVerticalScrollBar(),palette);body.add(scroll);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));actions.setOpaque(false);int[] result={-1};for(int i=0;i<choices.length;i++){final int choice=i;JButton button=new ModernButton(choices[i],null,palette,i==choices.length-1);button.addActionListener(e->{result[0]=choice;dialog.dispose();});actions.add(button);}body.add(actions,BorderLayout.SOUTH);dialog.setContentPane(body);dialog.setSize(520,230);dialog.setMinimumSize(new Dimension(420,200));dialog.getRootPane().registerKeyboardAction(e->dialog.dispose(),KeyStroke.getKeyStroke("ESCAPE"),JComponent.WHEN_IN_FOCUSED_WINDOW);dialog.setLocationRelativeTo(parent);dialog.setVisible(true);return result[0];}
}
